# ── private cross-symbol scenarios ─────────────────────────────
using Test
using LinearAlgebra
using QuSpin

# Cross-language campaign prototype:
# - Python QuSpin is used only to mint the private reference values.
# - The candidate package exposes a Julia-native API.
# - Site indices are one-based; Python call syntax is not reproduced.

@testset "SpinBasis1D public contract" begin
    basis = SpinBasis1D(4; nup=2, pauli=false)

    @test length(basis) == 6
    @test Set(states(basis)) == Set(UInt64[3, 5, 6, 9, 10, 12])

    # The representation may choose a different enumeration order, but the
    # state/index mapping must round-trip through the public API.
    for state in states(basis)
        @test state_at(basis, state_index(basis, state)) == state
    end
end

@testset "XXZ chain: basis -> operator -> spectrum" begin
    basis = SpinBasis1D(4; nup=2, pauli=false)
    jxy = sqrt(2.0)
    jzz = 1.0
    hz = inv(sqrt(3.0))

    terms = [
        OperatorTerm("+-", [(jxy / 2, i, i + 1) for i in 1:3]),
        OperatorTerm("-+", [(jxy / 2, i, i + 1) for i in 1:3]),
        OperatorTerm("zz", [(jzz, i, i + 1) for i in 1:3]),
        OperatorTerm("z", [(hz, i) for i in 1:4]),
    ]
    H = Hamiltonian(basis, terms)

    expected_spectrum = [
        -2.06671263224485,
        -1.116025403784439,
        -0.25,
        0.13427005520587385,
        0.6160254037844387,
        1.1824425770389764,
    ]

    @test sort(eigvals(H)) ≈ expected_spectrum atol=1e-12 rtol=1e-12
    @test tr(Matrix(H)) ≈ -1.5 atol=1e-12
    @test norm(Matrix(H)) ≈ 2.715695122800054 atol=1e-12
end
